def solve_range_volumes(text):
    tokens = text.split()
    n, q = int(tokens[0]), int(tokens[1])
    pre = [0]
    for v in tokens[2:2 + n]:
        pre.append(pre[-1] + int(v))
    out = []
    pos = 2 + n
    for _ in range(q):
        l, r = int(tokens[pos]), int(tokens[pos + 1])
        pos += 2
        out.append(str(pre[r] - pre[l - 1]))
    return '\n'.join(out)
